def quality(prediction_rows, label_rows):
    cohort = {}
    rejected = []
    seen_prediction_ids = {}
    seen = {}
    for row in prediction_rows:
        key = row['prediction_id']
        if key in seen_prediction_ids:
            return {'status': 'duplicate_prediction'}
        seen_prediction_ids[key] = row
    for row in label_rows:
        key = row['prediction_id']
        if key in seen:
